            ("from django.contrib.auth.signals import user_logged_in, user_login_failed", "The two announcements we listen to."),
            ("from django.core.cache import cache", "Where the failure counts are kept."),
            ("from django.dispatch import receiver", "`@receiver(...)` connects a function to a signal."),
            ("MAX_FAILURES = 5", "How many wrong passwords are allowed..."),
            ("LOCKOUT_SECONDS = 15 * 60", "...and for how long they're remembered: 15 minutes."),
